-- Player Speed Boost Script\n\nlocal Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\n\n-- Get the local player\nlocal player = Players.LocalPlayer\n\n-- Get the remote event\nlocal speedBoostEvent = ReplicatedStorage:WaitForChild("SpeedBoostEvent")\n\n-- Function to apply the speed boost\nlocal function applySpeedBoost()\n    local character = player.Character or player.CharacterAdded:Wait()\n    local humanoid = character:WaitForChild("Humanoid")\n    \n    -- Apply the speed boost\n    humanoid.WalkSpeed = humanoid.WalkSpeed * 2\n    \n    -- Set a timer to remove the speed boost after a certain time\n    delay(30, function()\n        humanoid.WalkSpeed = humanoid.WalkSpeed / 2\n    end)\nend\n\n-- Connect the remote event to the speed boost function\nspeedBoostEvent.OnClientEvent:Connect(applySpeedBoost)